/** Answers the scope override category one scoped package name hits, or null. */
function scopeCategory(name: string): string | null {
  for (const o of SCOPE_OVERRIDES) {
    for (const re of o.res) {
      if (re.test(name)) return o.cat;
    }
  }
  return null;
}

